// Calculate ROI metrics for yesterday
// Formula: 
//   Research hours saved = articles * 0.5h + signals * 2h + content_ideas * 1.5h + competitor_events * 3h
//   Value delivered = research_hours * $150/hr (analyst rate)

const metricDate = new Date();
metricDate.setDate(metricDate.getDate() - 1);
const dateStr = metricDate.toISOString().split('T')[0];

const articlesCollected = parseInt($('Count Articles Collected Yesterday').first().json.articles_collected) || 0;
const signalsDetected = parseInt($('Count Signals Detected Yesterday').first().json.signals_detected) || 0;
const contentIdeasGenerated = parseInt($('Count Content Ideas Generated Yesterday').first().json.content_ideas_generated) || 0;
const competitorEvents = parseInt($('Count Competitor Events Yesterday').first().json.competitor_events) || 0;
const painPointsDetected = parseInt($('Count Pain Points Yesterday').first().json.pain_points_detected) || 0;

// ROI Calculation
const ARTICLE_HOURS = 0.5;      // 30 min per article manually reviewed
const SIGNAL_HOURS = 2.0;       // 2 hours to manually identify each signal
const CONTENT_IDEA_HOURS = 1.5; // 1.5 hours to develop content idea from scratch
const COMPETITOR_EVENT_HOURS = 3.0; // 3 hours for competitor research per event
const PAIN_POINT_HOURS = 1.0;   // 1 hour for pain point research
const ANALYST_HOURLY_RATE = 150; // $150/hr analyst cost

const researchHoursSaved = (
  articlesCollected * ARTICLE_HOURS +
  signalsDetected * SIGNAL_HOURS +
  contentIdeasGenerated * CONTENT_IDEA_HOURS +
  competitorEvents * COMPETITOR_EVENT_HOURS +
  painPointsDetected * PAIN_POINT_HOURS
);

const estimatedValueUSD = Math.round(researchHoursSaved * ANALYST_HOURLY_RATE);

return [{
  json: {
    metric_date: dateStr,
    articles_collected: articlesCollected,
    signals_detected: signalsDetected,
    content_ideas_generated: contentIdeasGenerated,
    competitor_events: competitorEvents,
    pain_points_detected: painPointsDetected,
    research_hours_saved: Math.round(researchHoursSaved * 10) / 10,
    estimated_value_usd: estimatedValueUSD,
    formula_details: {
      article_hours: `${articlesCollected} × ${ARTICLE_HOURS}h = ${articlesCollected * ARTICLE_HOURS}h`,
      signal_hours: `${signalsDetected} × ${SIGNAL_HOURS}h = ${signalsDetected * SIGNAL_HOURS}h`,
      content_idea_hours: `${contentIdeasGenerated} × ${CONTENT_IDEA_HOURS}h = ${contentIdeasGenerated * CONTENT_IDEA_HOURS}h`,
      competitor_event_hours: `${competitorEvents} × ${COMPETITOR_EVENT_HOURS}h = ${competitorEvents * COMPETITOR_EVENT_HOURS}h`,
      pain_point_hours: `${painPointsDetected} × ${PAIN_POINT_HOURS}h = ${painPointsDetected * PAIN_POINT_HOURS}h`,
      analyst_rate: `$${ANALYST_HOURLY_RATE}/hr`
    },
    calculated_at: new Date().toISOString()
  }
}];

// Check if today is Monday for weekly summary
const today = new Date();
const isMonday = today.getDay() === 1;
const weeklyMetrics = $('Compute Weekly Trend').first().json;
const todayMetrics = $('Calculate ROI Metrics').first().json;

return [{
  json: {
    is_monday: isMonday,
    today_metrics: todayMetrics,
    weekly_metrics: weeklyMetrics
  }
}];

